    [Theory]
    [MemberData(nameof(Cases))]
    public void Cov_and_eigh_equal_Blenders_numpy_bit_for_bit(string index, string points, string cov, string w, string v, string axle)
    {
        var flat = points.Split(',').Select(H).ToArray();
        var pts = new List<double[]>();
        for (int i = 0; i < flat.Length; i += 3) pts.Add(new[] { flat[i], flat[i + 1], flat[i + 2] });
        var c = BlenderNumpy.CovOfCentred(pts);
        Assert.Equal(cov, string.Join(",", c.Select(B)));
        var r = BlenderNumpy.Eigh3(c);
        Assert.True(r.HasValue, "case " + index + " declined");
        Assert.Equal(w, string.Join(",", r.Value.w.Select(B)));
        Assert.Equal(v, string.Join(",", r.Value.v.Select(B)));
        // the axle: float32 components, the squares summed in double from the last, times 1.0f / the float root
        float x = (float)r.Value.v[0], y = (float)r.Value.v[3], z = (float)r.Value.v[6];
        double d = 0.0; d += (double)z * z; d += (double)y * y; d += (double)x * x;
        float s = (float)Math.Sqrt(d), f = (float)(1.0f / s);
        Assert.Equal(axle, string.Join(",", new double[] { (float)(x * f), (float)(y * f), (float)(z * f) }.Select(B)));
    }

    [Fact]
    public void A_zero_matrix_gives_the_identity_and_a_NaN_one_declines()
    {
        // Blender's numpy: eigh(zeros((3, 3))) = ([0, 0, 0], identity); eigh of all NaN raises LinAlgError (no convergence)
        var r = BlenderNumpy.Eigh3(new double[9]);
        Assert.True(r.HasValue);
        Assert.Equal(new double[3], r.Value.w);
        Assert.Equal(new double[] { 1, 0, 0, 0, 1, 0, 0, 0, 1 }, r.Value.v);
        var nan = new double[9]; for (int i = 0; i < 9; i++) nan[i] = double.NaN;
        Assert.False(BlenderNumpy.Eigh3(nan).HasValue);
    }

    [Fact]
    public void One_point_has_no_covariance()
    {
        Assert.Null(BlenderNumpy.CovOfCentred(new List<double[]> { new[] { 1.0, 2.0, 3.0 } }));
    }
